/**
 * Nickname check for the profile screen (task M2-11, PLAN.md §6.7). Pure.
 *
 * A nickname is 1–16 chars of letters, digits, spaces, `'` and `-`, and must not hit the safety
 * blocklist (`src/content/wordlists/blocklist.txt`, M1-10). The blocklist itself never ships: the
 * game gets only hashes of every blocked form (`./filter-data.ts`, generated by
 * `npm run tool -- gen-nickname-filter`). The rules match M1-10's `blocklistHits`:
 *
 * - each word, and each run of words, against the terms and their inflections (allowed words
 *   already removed from the derived forms at build time);
 * - strict terms inside any word;
 * - the same again with look-alike spellings undone (`k1ll`, `sh-it`), `1` read as `i` and as `l`.
 *
 * A nickname is also checked with its words joined ("b a d" → "bad"), which word lists don't need
 * but a name does: it errs on the side of a false alarm, and a child can always pick another name.
 */
import { NICKNAME_JOINED, NICKNAME_PHRASES, NICKNAME_STRICT, NICKNAME_WORDS } from "./filter-data";
import { hashText } from "./hash";

/** Longest nickname, in characters. Same as `NAME_MAX` in `src/save/schema.ts`. */
export const NICKNAME_MAX = 16;

/** Chars a nickname may use. */
export const NICKNAME_CHAR = /^[A-Za-z0-9 '-]$/;

export type NicknameCheck =
  | { ok: true; name: string }
  | { ok: false; reason: "empty" | "tooLong" | "notAllowed" };

const setOf = (packed: string): ReadonlySet<string> =>
  new Set(packed.split(" ").filter((h) => h !== ""));

let sets: {
  words: ReadonlySet<string>;
  strict: ReadonlySet<string>;
  phrases: ReadonlySet<string>;
  joined: ReadonlySet<string>;
} | null = null;

function filterSets(): NonNullable<typeof sets> {
  sets ??= {
    words: setOf(NICKNAME_WORDS),
    strict: setOf(NICKNAME_STRICT),
    phrases: setOf(NICKNAME_PHRASES),
    joined: setOf(NICKNAME_JOINED),
  };
  return sets;
}

/** Lowercase a-z words; every other char separates words (as M1-10's `wordsOf`). */
export const wordsOf = (item: string): string[] =>
  item
    .toLowerCase()
    .split(/[^a-z]+/)
    .filter((w) => w !== "");

/** Look-alike chars mapped to letters inside a word (as M1-10). `1` is tried as `i` and `l`. */
const LOOKALIKES: Readonly<Record<string, string>> = {
  "0": "o",
  "3": "e",
  "4": "a",
  "5": "s",
  "7": "t",
  "@": "a",
  $: "s",
  "!": "i",
  "|": "l",
};

const PRONOUN_STEMS: ReadonlySet<string> = new Set(
  "i you he she it we they there that who what where when why how this here let".split(" "),
);
const NOT_STEMS: ReadonlySet<string> = new Set(
  "ca wo do does did is are was were has have had could would should must need ai sha".split(" "),
);

function isContraction(token: string): boolean {
  const m = /^([a-z]+)'(ll|d|re|ve|m|s|t)$/.exec(token);
  const stem = m?.[1];
  if (stem === undefined) return false;
  if (m?.[2] === "t") return stem.endsWith("n") && NOT_STEMS.has(stem.slice(0, -1));
  return PRONOUN_STEMS.has(stem);
}

/** The words with disguises undone, in two variants (as M1-10's `normalizedWords`). */
export function normalizedWords(item: string): string[][] {
  const tokens = item
    .toLowerCase()
    .split(/\s+/)
    .map((t) => t.replace(/^[^a-z0-9@$|]+|[^a-z0-9@$|]+$/g, ""))
    .filter((t) => /[a-z@$|]/.test(t));
  return (["i", "l"] as const).map((one) =>
    tokens
      .flatMap((t) =>
        isContraction(t)
          ? t.split("'")
          : [t.replace(/[^a-z]/g, (c) => (c === "1" ? one : (LOOKALIKES[c] ?? "")))],
      )
      .filter((w) => w !== ""),
  );
}

function wordHit(w: string, s: NonNullable<typeof sets>): boolean {
  if (s.words.has(hashText(w))) return true;
  for (let i = 0; i < w.length; i++) {
    for (let j = i + 1; j <= w.length; j++) {
      if (s.strict.has(hashText(w.slice(i, j)))) return true;
    }
  }
  return false;
}

function wordsHit(words: readonly string[], s: NonNullable<typeof sets>): boolean {
  if (words.some((w) => wordHit(w, s))) return true;
  for (let i = 0; i < words.length; i++) {
    for (let j = i + 2; j <= words.length; j++) {
      if (s.phrases.has(hashText(words.slice(i, j).join(" ")))) return true;
    }
  }
  return false;
}

/**
 * True when `text` hits the blocklist the way M1-10's validator reads word lists (plain and
 * look-alike words, runs of words). No joining; {@link checkNickname} adds that.
 */
export function blockedText(text: string): boolean {
  const s = filterSets();
  return [wordsOf(text), ...normalizedWords(text)].some((words) => wordsHit(words, s));
}

/** Collapses runs of spaces and trims the ends. */
export const tidyNickname = (raw: string): string => raw.replace(/\s+/g, " ").trim();

/** Checks a typed nickname. On success, `name` is the tidied text to save. */
export function checkNickname(raw: string): NicknameCheck {
  const name = tidyNickname(raw);
  if (name === "") return { ok: false, reason: "empty" };
  const chars = Array.from(name);
  if (chars.length > NICKNAME_MAX) return { ok: false, reason: "tooLong" };
  if (!chars.every((c) => NICKNAME_CHAR.test(c))) return { ok: false, reason: "notAllowed" };
  if (blockedText(name)) return { ok: false, reason: "notAllowed" };
  const s = filterSets();
  for (const words of [wordsOf(name), ...normalizedWords(name)]) {
    const joined = words.join("");
    if (joined !== "" && (wordHit(joined, s) || s.joined.has(hashText(joined)))) {
      return { ok: false, reason: "notAllowed" };
    }
    if (words.some((w) => s.joined.has(hashText(w)))) return { ok: false, reason: "notAllowed" };
  }
  return { ok: true, name };
}
